-- BÜCÜRÜKTOYS ürün yönetimi — Supabase SQL Editor'da tek sefer çalıştırın.
create table if not exists public.products (
  id bigint generated by default as identity primary key,
  sku text not null unique,
  name text not null,
  category text not null check (category in ('outdoor','fun','skill','sensory','stationery','accessory','3d')),
  pack text not null,
  description text,
  price numeric(12,2) check (price is null or price >= 0),
  cost_price numeric(12,2) check (cost_price is null or cost_price >= 0),
  stock integer not null default 0 check (stock >= 0),
  barcode text,
  min_order_packages integer not null default 1 check (min_order_packages >= 1),
  low_stock_threshold integer not null default 5 check (low_stock_threshold >= 0),
  supplier text,
  age_group text,
  conformity_declaration text,
  product_dimensions text,
  carton_dimensions text,
  carton_desi numeric(10,2) check (carton_desi is null or carton_desi >= 0),
  carton_weight_kg numeric(10,3) check (carton_weight_kg is null or carton_weight_kg >= 0),
  origin_country text,
  safety_note text,
  license_note text,
  image_url text,
  gallery jsonb not null default '[]'::jsonb check (jsonb_typeof(gallery) = 'array'),
  is_price_visible boolean not null default false,
  is_published boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Mevcut kurulumları veri kaybı olmadan günceller.
alter table public.products add column if not exists cost_price numeric(12,2) check (cost_price is null or cost_price >= 0);
alter table public.products add column if not exists barcode text;
alter table public.products add column if not exists min_order_packages integer not null default 1 check (min_order_packages >= 1);
alter table public.products add column if not exists low_stock_threshold integer not null default 5 check (low_stock_threshold >= 0);
alter table public.products add column if not exists supplier text;
alter table public.products add column if not exists age_group text;
alter table public.products add column if not exists conformity_declaration text;
alter table public.products add column if not exists product_dimensions text;
alter table public.products add column if not exists carton_dimensions text;
alter table public.products add column if not exists carton_desi numeric(10,2) check (carton_desi is null or carton_desi >= 0);
alter table public.products add column if not exists carton_weight_kg numeric(10,3) check (carton_weight_kg is null or carton_weight_kg >= 0);
alter table public.products add column if not exists origin_country text;
alter table public.products add column if not exists safety_note text;
alter table public.products add column if not exists license_note text;

create index if not exists products_public_order_idx on public.products (is_published, sort_order, id);
alter table public.products enable row level security;

drop policy if exists "Public can read published products" on public.products;
create policy "Public can read published products"
on public.products for select
to anon, authenticated
using (is_published = true);

