-- Müşteri teklif talepleri
create table if not exists public.quotes (
  id bigint generated by default as identity primary key,
  reference text not null unique default ('TK-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(random()::text), 1, 5))),
  customer_name text,
  company_name text,
  phone text,
  note text,
  status text not null default 'new' check (status in ('new','contacted','quoted','approved','completed','cancelled')),
  total_lines integer not null default 0,
  total_packages integer not null default 0,
  source text not null default 'catalog',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.quote_items (
  id bigint generated by default as identity primary key,
  quote_id bigint not null references public.quotes(id) on delete cascade,
  product_id bigint references public.products(id) on delete set null,
  sku text not null,
  product_name text not null,
  pack text not null,
  package_quantity integer not null check (package_quantity > 0 and package_quantity <= 999),
  created_at timestamptz not null default now()
);

create index if not exists quotes_status_created_idx on public.quotes (status, created_at desc);
create index if not exists quote_items_quote_idx on public.quote_items (quote_id);
create index if not exists quote_items_product_idx on public.quote_items (product_id);
alter table public.quotes enable row level security;
alter table public.quote_items enable row level security;

create or replace function public.create_catalog_quote(
  p_customer_name text,
  p_company_name text,
  p_phone text,
  p_note text,
  p_items jsonb
) returns table(id bigint, reference text)
language plpgsql
security definer
set search_path = public
as $$
declare
  created_quote public.quotes;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 100 then
    raise exception 'invalid_quote_items';
  end if;
  insert into public.quotes (customer_name, company_name, phone, note, total_lines, total_packages)
  values (
    nullif(trim(p_customer_name), ''),
    nullif(trim(p_company_name), ''),
    nullif(trim(p_phone), ''),
    nullif(trim(p_note), ''),
    jsonb_array_length(p_items),
    (select coalesce(sum((item->>'quantity')::integer), 0) from jsonb_array_elements(p_items) item)
  ) returning * into created_quote;
  insert into public.quote_items (quote_id, product_id, sku, product_name, pack, package_quantity)
  select created_quote.id, (item->>'productId')::bigint, item->>'sku', item->>'name', item->>'pack', (item->>'quantity')::integer
  from jsonb_array_elements(p_items) item;
  return query select created_quote.id, created_quote.reference;
end;
$$;

revoke all on function public.create_catalog_quote(text, text, text, text, jsonb) from public, anon, authenticated;

-- Stok hareket geçmişi
create table if not exists public.inventory_movements (
  id bigint generated by default as identity primary key,
  product_id bigint not null references public.products(id) on delete cascade,
  change integer not null check (change <> 0),
  stock_before integer not null,
  stock_after integer not null check (stock_after >= 0),
  reason text,
  actor_email text,
  created_at timestamptz not null default now()
);

create index if not exists inventory_product_created_idx on public.inventory_movements (product_id, created_at desc);
alter table public.inventory_movements enable row level security;

create or replace function public.adjust_product_stock(
  p_product_id bigint,
  p_change integer,
  p_reason text default null,
  p_actor_email text default null
) returns public.products
language plpgsql
security definer
set search_path = public
as $$
declare
  current_product public.products;
  next_stock integer;
begin
  select * into current_product from public.products where id = p_product_id for update;
  if not found then raise exception 'product_not_found'; end if;
  next_stock := current_product.stock + p_change;
  if next_stock < 0 then raise exception 'insufficient_stock'; end if;
  update public.products set stock = next_stock, updated_at = now() where id = p_product_id returning * into current_product;
  insert into public.inventory_movements (product_id, change, stock_before, stock_after, reason, actor_email)
  values (p_product_id, p_change, next_stock - p_change, next_stock, nullif(trim(p_reason), ''), p_actor_email);
  return current_product;
end;
$$;

revoke all on function public.adjust_product_stock(bigint, integer, text, text) from public, anon, authenticated;

