-- Teklif RPC'sini anonim çağrılarda dahi ürün verisini veritabanından doğrulayacak şekilde sıkılaştırır.
create or replace function public.create_catalog_quote(
  p_customer_name text,
  p_company_name text,
  p_phone text,
  p_note text,
  p_items jsonb
) returns table(id bigint, reference text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  created_quote public.quotes;
  inserted_lines integer;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1 or jsonb_array_length(p_items) > 100 then
    raise exception 'invalid_quote_items';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_items) item
    where coalesce(item ->> 'productId', '') !~ '^[1-9][0-9]*$'
       or coalesce(item ->> 'quantity', '') !~ '^[1-9][0-9]*$'
       or (item ->> 'quantity')::integer > 999
  ) then
    raise exception 'invalid_quote_items';
  end if;

  insert into public.quotes (customer_name, company_name, phone, note, total_lines, total_packages)
  values (
    nullif(left(trim(p_customer_name), 120), ''),
    nullif(left(trim(p_company_name), 160), ''),
    nullif(left(trim(p_phone), 30), ''),
    nullif(left(trim(p_note), 1000), ''),
    jsonb_array_length(p_items),
    (select sum((item ->> 'quantity')::integer) from jsonb_array_elements(p_items) item)
  ) returning * into created_quote;

  insert into public.quote_items (quote_id, product_id, sku, product_name, pack, package_quantity)
  select created_quote.id, product.id, product.sku, product.name, product.pack, (item ->> 'quantity')::integer
  from jsonb_array_elements(p_items) item
  join public.products product on product.id = (item ->> 'productId')::bigint and product.is_published;
  get diagnostics inserted_lines = row_count;
  if inserted_lines <> jsonb_array_length(p_items) then raise exception 'invalid_or_unpublished_product'; end if;

  return query select created_quote.id, created_quote.reference;
end;
$$;
revoke all on function public.create_catalog_quote(text, text, text, text, jsonb) from public, anon, authenticated;
-- Resmi veri sorumlusu kimligi tamamlanana kadar kisisel veri kaydi kapali.

create or replace function public.create_dealer_application(
  p_company_name text, p_contact_name text, p_phone text, p_email text default null,
  p_city text default null, p_district text default null, p_tax_office text default null,
  p_tax_number text default null, p_business_type text default null,
  p_monthly_volume text default null, p_note text default null
) returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare created_id bigint;
begin
  if length(trim(coalesce(p_company_name, ''))) < 1
     or length(trim(coalesce(p_contact_name, ''))) < 1
     or length(regexp_replace(coalesce(p_phone, ''), '\\D', '', 'g')) < 10 then
    raise exception 'invalid_application';
  end if;
  insert into public.dealer_applications (
    company_name, contact_name, phone, email, city, district, tax_office, tax_number,
    business_type, monthly_volume, note
  ) values (
    left(trim(p_company_name), 160), left(trim(p_contact_name), 120), left(trim(p_phone), 30),
    nullif(left(trim(p_email), 160), ''), nullif(left(trim(p_city), 80), ''),
    nullif(left(trim(p_district), 80), ''), nullif(left(trim(p_tax_office), 120), ''),
    nullif(left(trim(p_tax_number), 40), ''), nullif(left(trim(p_business_type), 120), ''),
    nullif(left(trim(p_monthly_volume), 120), ''), nullif(left(trim(p_note), 1500), '')
  ) returning id into created_id;
  return created_id;
end;
$$;
revoke all on function public.create_dealer_application(text,text,text,text,text,text,text,text,text,text,text) from public, anon, authenticated;

create or replace function public.create_print_request(
  p_customer_name text, p_company_name text, p_phone text, p_email text,
  p_model_name text, p_quantity integer, p_material text default null,
  p_color text default null, p_dimensions text default null, p_model_url text default null,
  p_note text default null
) returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare created_id bigint;
begin
  if length(trim(coalesce(p_customer_name, ''))) < 1
     or length(regexp_replace(coalesce(p_phone, ''), '\\D', '', 'g')) < 10
     or length(trim(coalesce(p_model_name, ''))) < 1
     or p_quantity is null or p_quantity < 1 or p_quantity > 100000 then
    raise exception 'invalid_print_request';
  end if;
  insert into public.print_requests (
    customer_name, company_name, phone, email, model_name, quantity,
    material, color, dimensions, model_url, note
  ) values (
    left(trim(p_customer_name), 120), nullif(left(trim(p_company_name), 160), ''), left(trim(p_phone), 30),
    nullif(left(trim(p_email), 160), ''), left(trim(p_model_name), 160), p_quantity,
    nullif(left(trim(p_material), 80), ''), nullif(left(trim(p_color), 80), ''),
    nullif(left(trim(p_dimensions), 120), ''), nullif(left(trim(p_model_url), 1000), ''),
    nullif(left(trim(p_note), 2000), '')
  ) returning id into created_id;
  return created_id;
end;
$$;
revoke all on function public.create_print_request(text,text,text,text,text,integer,text,text,text,text,text) from public, anon, authenticated;

create or replace function public.record_catalog_event(
  p_event_type text, p_product_id bigint default null, p_sku text default null,
  p_session_id text default null, p_metadata jsonb default '{}'::jsonb
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_event_type not in ('product_view','offer_add','product_share','whatsapp_click','catalog_search','category_filter','catalog_print')
     or jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid_event';
  end if;
  insert into public.analytics_events (event_type, product_id, sku, session_id, metadata)
  values (p_event_type, p_product_id, nullif(left(p_sku, 40), ''), nullif(left(p_session_id, 80), ''), coalesce(p_metadata, '{}'::jsonb));
end;
$$;
revoke all on function public.record_catalog_event(text,bigint,text,text,jsonb) from public, anon, authenticated;
grant execute on function public.record_catalog_event(text,bigint,text,text,jsonb) to anon, authenticated;

-- Stok RPC'si yalnızca admin_users tablosundaki oturumlara açıktır.
create or replace function public.adjust_product_stock(
  p_product_id bigint,
  p_change integer,
  p_reason text default null,
  p_actor_email text default null
) returns public.products
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_product public.products;
  next_stock integer;
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  select * into current_product from public.products where id = p_product_id for update;
  if not found then raise exception 'product_not_found'; end if;
  next_stock := current_product.stock + p_change;
  if next_stock < 0 then raise exception 'insufficient_stock'; end if;
  update public.products set stock = next_stock, updated_at = now() where id = p_product_id returning * into current_product;
  insert into public.inventory_movements (product_id, change, stock_before, stock_after, reason, actor_email)
  values (
    p_product_id, p_change, next_stock - p_change, next_stock,
    nullif(left(trim(p_reason), 300), ''), lower(coalesce(auth.jwt() ->> 'email', p_actor_email))
  );
  return current_product;
end;
$$;
revoke all on function public.adjust_product_stock(bigint, integer, text, text) from public, anon, authenticated;
grant execute on function public.adjust_product_stock(bigint, integer, text, text) to authenticated;

