drop function if exists public.create_print_request(text,text,text,text,text,integer,text,text,text,text,text);
create or replace function public.create_print_request(
  p_customer_name text,
  p_company_name text,
  p_phone text,
  p_email text,
  p_model_name text,
  p_quantity integer,
  p_material text default null,
  p_color text default null,
  p_dimensions text default null,
  p_model_url text default null,
  p_note text default null,
  p_selected_product_sku text default null,
  p_selected_product_name text default null,
  p_estimated_price numeric default null,
  p_file_paths jsonb default '[]'::jsonb
) returns table(id bigint, reference text)
language plpgsql
security definer
set search_path = ''
as $$
declare created_request public.print_requests;
begin
  if length(trim(coalesce(p_customer_name, ''))) < 1
     or length(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g')) < 10
     or length(trim(coalesce(p_model_name, ''))) < 1
     or p_quantity is null or p_quantity < 1 or p_quantity > 100000
     or jsonb_typeof(coalesce(p_file_paths, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_file_paths, '[]'::jsonb)) > 3 then
    raise exception 'invalid_print_request';
  end if;
  insert into public.print_requests (
    customer_name, company_name, phone, email, model_name, quantity,
    material, color, dimensions, model_url, note, selected_product_sku,
    selected_product_name, estimated_price, file_paths
  ) values (
    left(trim(p_customer_name), 120),
    nullif(left(trim(p_company_name), 160), ''),
    left(trim(p_phone), 30),
    nullif(left(trim(p_email), 160), ''),
    left(trim(p_model_name), 180),
    p_quantity,
    nullif(left(trim(p_material), 120), ''),
    nullif(left(trim(p_color), 120), ''),
    nullif(left(trim(p_dimensions), 160), ''),
    nullif(left(trim(p_model_url), 1000), ''),
    nullif(left(trim(p_note), 2500), ''),
    nullif(left(trim(p_selected_product_sku), 40), ''),
    nullif(left(trim(p_selected_product_name), 180), ''),
    case when p_estimated_price is null or p_estimated_price < 0 then null else round(p_estimated_price, 2) end,
    coalesce(p_file_paths, '[]'::jsonb)
  ) returning * into created_request;
  return query select created_request.id, created_request.reference;
end;
$$;
revoke all on function public.create_print_request(text,text,text,text,text,integer,text,text,text,text,text,text,text,numeric,jsonb) from public, anon, authenticated;

